class InspectionViewer:
    def __init__(self, root):
        self.root = root
        self.root.title("KLA Semiconductor Inspection Photo Viewer (Phase 13)")
        self.root.geometry("1100x480")
        self.root.configure(bg="#12141a")

        self.idx = 0

        # Header controls
        top_frame = tk.Frame(root, bg="#12141a", pady=10)
        top_frame.pack(fill="x", padx=15)

        tk.Label(top_frame, text="KLA Semiconductor Inspection Viewer", font=("Segoe UI", 13, "bold"), fg="#58a6ff", bg="#12141a").pack(side="left")

        btn_prev = tk.Button(top_frame, text="◀ Prev", command=self.prev_img, bg="#21262d", fg="#c9d1d9", relief="flat", padx=12, pady=4)
        btn_prev.pack(side="left", padx=15)

        self.combo = ttk.Combobox(top_frame, values=[f"{d['sample_id']} (v2: {d['v2_p']:.2f} dB)" for d in data], state="readonly", width=32)
        self.combo.current(0)
        self.combo.bind("<<ComboboxSelected>>", self.on_select)
        self.combo.pack(side="left")

        btn_next = tk.Button(top_frame, text="Next ▶", command=self.next_img, bg="#21262d", fg="#c9d1d9", relief="flat", padx=12, pady=4)
        btn_next.pack(side="left", padx=10)

        self.delta_label = tk.Label(top_frame, text="", font=("Segoe UI", 10, "bold"), fg="#3fb950", bg="#12141a")
        self.delta_label.pack(side="right")

        # Cards frame
        self.cards_frame = tk.Frame(root, bg="#12141a")
        self.cards_frame.pack(fill="both", expand=True, padx=15, pady=5)

        self.panels = []
        titles = [
            "1. Damaged Input (128x128)",
            "2. Original Model (best.pth)",
            "3. Fine-Tuned v2 (🌟 finetuned_v2.pth)",
            "4. Ground Truth Clean (256x256)"
        ]

        for i, title in enumerate(titles):
            f = tk.Frame(self.cards_frame, bg="#161b22", bd=1, relief="solid")
            f.grid(row=0, column=i, padx=8, pady=5, sticky="nsew")
            self.cards_frame.grid_columnconfigure(i, weight=1)

            t_lbl = tk.Label(f, text=title, font=("Segoe UI", 9, "bold"), fg="#3fb950" if i==2 else "#8b949e", bg="#161b22", pady=4)
            t_lbl.pack()

            img_lbl = tk.Label(f, bg="#000")
            img_lbl.pack(padx=5, pady=5)

            stat_lbl = tk.Label(f, text="", font=("Segoe UI", 9), fg="#e6edf3", bg="#161b22", pady=4)
            stat_lbl.pack()

            self.panels.append((img_lbl, stat_lbl))

        self.root.bind("<Left>", lambda e: self.prev_img())
        self.root.bind("<Right>", lambda e: self.next_img())
        self.show()

    def show(self):
        item = data[self.idx]
        sid = item["sample_id"]
        self.combo.current(self.idx)

        paths = [
            ROOT / "degraded" / f"{sid}.png",
            ROOT / "restored_best" / f"{sid}.png",
            ROOT / "restored_finetuned" / f"{sid}.png",
            ROOT / "clean" / f"{sid}.png"
        ]

        stats_texts = [
            "Noisy + Downsampled",
            f"PSNR: {item['best_p']:.2f} dB | SSIM: {item['best_s']:.4f}",
            f"PSNR: {item['v2_p']:.2f} dB | SSIM: {item['v2_s']:.4f}",
            "Pristine Ground Truth"
        ]

        self.photos = []
        for i, (img_p, text) in enumerate(zip(paths, stats_texts)):
            img = Image.open(img_p).resize((220, 220), Image.NEAREST)
            photo = ImageTk.PhotoImage(img)
            self.photos.append(photo)
            self.panels[i][0].configure(image=photo)
            self.panels[i][1].configure(text=text)

        d_str = f"v2 Delta: {item['delta_p']:+.2f} dB PSNR / {item['delta_s']:+.4f} SSIM over best.pth"
        self.delta_label.configure(text=d_str)

    def prev_img(self):
        if self.idx > 0:
            self.idx -= 1
            self.show()

    def next_img(self):
        if self.idx < len(data) - 1:
            self.idx += 1
            self.show()

    def on_select(self, e):
        self.idx = self.combo.current()
        self.show()

if __name__ == "__main__":
    app_root = tk.Tk()
    viewer = InspectionViewer(app_root)
    app_root.mainloop()
